// Monta o resumo do dia anterior, no horário de Brasília (seção 4.5): só números, sem dados pessoais. Da Meta sem campanha, vão só
// os números dos leads no CRM. As datas são comparadas aqui, e não no filtro da Data Table: no n8n local, ele compara texto, e um
// "maior que" no mesmo dia não acha nada. O e-mail sai quando há algo a contar e, no dia do diaDoResumoSemanal, sempre, com os
// envios do site: é o sinal de que o n8n está rodando e o acompanhamento da cota de execuções.
const configuracao = $('Configuração').first().json;
const linhas = (no) => $(no).all().map((item) => item.json).filter((linha) => linha.id !== undefined);
const recusadas = linhas('Buscar as recusadas');
const pendentes = linhas('Buscar as pendentes');
const envios = linhas('Buscar os envios do site');

const fuso = 'America/Sao_Paulo';
const quando = (valor) => DateTime.fromJSDate(new Date(valor)).setZone(fuso);
const hoje = DateTime.now().setZone(fuso).startOf('day');
const ontem = hoje.minus({ days: 1 });
const desde = (inicio) => (linha) => {
  const data = quando(linha.criado_em);
  return data >= inicio && data < hoje;
};
const deOntem = recusadas.filter(desde(ontem));
const enviosDeOntem = envios.filter(desde(ontem)).length;
const enviosDe30Dias = envios.filter(desde(hoje.minus({ days: 30 }))).length;

const recusadasPeloCrm = deOntem.filter((linha) => String(linha.tipo).endsWith('_recusada'));
const porOrigem = {};
for (const linha of recusadasPeloCrm) {
  const origem = String(linha.tipo).replace(/_recusada$/, '');
  porOrigem[origem] = (porOrigem[origem] || 0) + 1;
}
const chaveErrada = deOntem.filter((linha) => linha.tipo === 'google_chave_errada').length;
const semCampanha = deOntem.filter((linha) => linha.tipo === 'meta_sem_campanha').map((linha) => linha.detalhe);
const barrados = deOntem.filter((linha) => linha.tipo === 'site_acima_do_limite').length;
const semLimite = deOntem.filter((linha) => linha.tipo === 'site_sem_limite').length;
const maisAntiga = pendentes.reduce((antiga, linha) => {
  const data = quando(linha.criado_em);
  return antiga === null || data < antiga ? data : antiga;
}, null);

const partes = [];
if (recusadasPeloCrm.length > 0) {
  partes.push('Entradas recusadas pelo CRM (400 ou 413): ' + recusadasPeloCrm.length);
  for (const origem of Object.keys(porOrigem).sort()) partes.push('  - ' + origem + ': ' + porOrigem[origem]);
}
if (chaveErrada > 0) partes.push('Envios ao Google com a chave errada (403): ' + chaveErrada);
if (semCampanha.length > 0) {
  partes.push('Leads da Meta que entraram sem a campanha: ' + semCampanha.length + ' (' + semCampanha.join(', ') + ')');
}
if (barrados > 0) partes.push('Envios do site barrados pelo limite: ' + barrados);
if (semLimite > 0) partes.push('Envios do site que foram ao CRM sem o limite, por falha na crm_envios_site: ' + semLimite);
if (pendentes.length > 0) {
  partes.push('Entradas esperando o reenvio: ' + pendentes.length + ', a mais antiga de ' + maisAntiga.toFormat('dd/MM HH:mm'));
}

const semanal = hoje.weekday === Number(configuracao.diaDoResumoSemanal);
const dia = ontem.toFormat('dd/MM/yyyy');
const texto = [
  'Resumo do n8n de ' + dia + ', no horário de Brasília.',
  '',
  'Envios do site: ' + enviosDeOntem + ' ontem e ' + enviosDe30Dias + ' nos 30 dias até ontem. Cada envio gasta uma execução do n8n.',
  ...(partes.length > 0 ? partes : ['Nada mais a contar.']),
  '',
  'As recusadas ficam ' + configuracao.diasRecusadas + ' dias na Data Table crm_entradas_recusadas, com os dados da entrada, e as pendentes, na crm_entradas_pendentes, até o reenvio. Este e-mail não traz nenhum dado das entradas.',
].join('\n');

return [{ json: { temAlgo: partes.length > 0 || semanal, assunto: '[CRM] Resumo do n8n de ' + dia, texto: texto } }];

// As recusadas com mais dias que o diasRecusadas do "Configuração" saem da tabela, pelo id (seção 4.5). A data é comparada aqui,
// e não no filtro da Data Table, que no n8n local compara texto.
const dias = Number($('Configuração').first().json.diasRecusadas);
const limite = DateTime.now().minus({ days: dias });
return $('Buscar as recusadas')
  .all()
  .map((item) => item.json)
  .filter((linha) => linha.id !== undefined && DateTime.fromJSDate(new Date(linha.criado_em)) < limite)
  .map((linha) => ({ json: { id: linha.id } }));

// Os envios do site com mais dias que o diasEnviosSite do "Configuração" saem da tabela, pelo id (seção 4.5). A data é comparada
// aqui, e não no filtro da Data Table, que no n8n local compara texto.
const dias = Number($('Configuração').first().json.diasEnviosSite);
const limite = DateTime.now().minus({ days: dias });
return $('Buscar os envios do site')
  .all()
  .map((item) => item.json)
  .filter((linha) => linha.id !== undefined && DateTime.fromJSDate(new Date(linha.criado_em)) < limite)
  .map((linha) => ({ json: { id: linha.id } }));
